//! National-language support shared by our `kernelbase.dll` and our C
//! runtime (ADR 0094), as host-tested code:
//!
//! - [`codepage`]: the code pages Poly converts (single-byte, the
//!   double-byte 932/936/949/950, UTF-8) and their conversions to and from
//!   UTF-16, lead and trail bytes.
//! - [`tables`]: the code page tables, generated by `cargo xtask
//!   nls-tables` from the Unicode Consortium's public mapping files.
//! - [`locale`]: the locales Poly knows, their names, code pages and
//!   number and currency formats.
//! - [`unicode`]: character classes (`ctype.h`'s bits) and simple case
//!   mapping of UTF-16 units.
//! - [`collate`]: Poly's documented collation and sort keys.
//!
//! `kernelbase` serves the conversions (`MultiByteToWideChar` and friends);
//! the C runtime converts through `kernel32` and links only the small
//! parts of this crate (lead and trail byte ranges, the locale table, the
//! classes, the collation), so the double-byte tables exist once.

#![no_std]

extern crate alloc;
#[cfg(test)]
extern crate std;

pub mod codepage;
pub mod collate;
pub mod locale;
#[rustfmt::skip]
pub mod tables;
pub mod unicode;
